/**
 * Helper to get a random entry filtered by category and difficulty
 */
export function selectSecretWord(
  category: string = 'All',
  difficulty: 'ALL' | 'EASY' | 'MEDIUM' | 'HARD' = 'ALL',
  excludeIds: string[] = []
): WordBankEntry {
  let pool = WORD_BANK.filter(entry => !excludeIds.includes(entry.id));

  if (category && category !== 'All') {
    pool = pool.filter(entry => entry.category.toLowerCase() === category.toLowerCase());
  }

  if (difficulty && difficulty !== 'ALL') {
    pool = pool.filter(entry => entry.difficulty === difficulty);
  }

  // Fallback to full pool if filter exhausted
  if (pool.length === 0) {
    pool = WORD_BANK;
  }

  const randomIndex = Math.floor(Math.random() * pool.length);
  return pool[randomIndex];
}

/**
 * Pick an ambiguous, suitable hint candidate for the imposter based on mode
 */
export function getSuitableHint(
  entry: WordBankEntry,
  mode: 'RELATED_WORD' | 'CATEGORY_ONLY' | 'NO_HINT'
): string | null {
  if (mode === 'NO_HINT') return null;
  if (mode === 'CATEGORY_ONLY') return entry.category.toUpperCase();

  // Mode is RELATED_WORD: Pick one hint candidate randomly
  if (!entry.hints || entry.hints.length === 0) {
    return entry.category.toUpperCase();
  }

  const hintIdx = Math.floor(Math.random() * entry.hints.length);
  return entry.hints[hintIdx];
}
